#[derive(Clone, Copy, PartialEq, Eq)]
enum Menu {
    Agent,
    /// The agent's brain: its program's settings, such as its model and effort.
    Model,
    Permission,
}

/// What a right-click opened a menu on, at the pointer. An agent's opens the agent menu
/// (`menu_at`) instead.
#[derive(Clone, PartialEq, Eq)]
enum Ctx {
    /// A message in the chat, by its id, and what's selected in it.
    Message(String, Option<String>),
    /// A server in the sidebar's foot, by its folder.
    Server(String),
    /// The sidebar's list of agents, under its last.
    Agents,
    /// A folder in the sidebar, by its id.
    Folder(String),
    /// A group chat in the sidebar, by its conversation.
    Room(String),
    /// The line over a reply in a group chat: the reply, and the agent that gave it.
    Resend(String, String),
    /// A table in a reply, by its rows, header first: the ways to copy it.
    Table(Vec<Vec<String>>),
    /// The composer's smiley.
    EmojiButton,
}

/// Words selected in a message, and where the selection ended: a small bar there has
/// Copy, Quote and, in an agent's reply, Ask about this (LOO-200).
#[derive(Clone)]
struct Picked {
    at: Point<Pixels>,
    message: String,
    text: String,
    agent: bool,
}

/// The Pinned popover while it's open (PLAN.md, "Pinned messages").
#[derive(Clone, Default)]
struct PinsPop {
    /// The conversation it opened on.
    chat: Option<String>,
    /// The pin the arrow keys are on, by message.
    lit: Option<String>,
    /// The pins opened with Show more, by message.
    open: HashSet<String>,
    /// The note at its foot, and when it came: Unpinned with Undo, or Copied.
    note: Option<(PinNote, Instant)>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum PinNote {
    Unpinned,
    Copied,
}

/// How long Unpinned, with its Undo, stays at the popover's foot, and Copied.
const UNPIN_SECS: u64 = 6;
const COPIED_MILLIS: u64 = 1600;
/// How wide the Pinned popover is, and how much of the window's height it takes at most.
const PINS_W: f32 = 460.0;
const PINS_TALL: f32 = 0.7;
/// The room a pin is drawn for: its pictures smaller than the chat's, a picture 200 wide.
const PIN_ROOM: i32 = 248;

/// The composer's + menu while it's open (PLAN.md, "The composer's + menu").
#[derive(Clone, Default)]
struct PlusMenu {
    /// The row lit in the menu, by its place among the menu's rows, all groups counted.
    lit: usize,
    /// The list open beside it, and the row lit in that once the keys have gone there.
    sub: Option<model::PlusSub>,
    sub_lit: Option<usize>,
    /// The routine that asks "Run now?" in its row, by id.
    confirm: Option<String>,
    /// Whether the clipboard held a picture as it opened.
    paste: bool,
}

/// Where the + menu's panels are on screen, for a click outside both, and each row
/// that opens a list beside the menu, for the list to open by.
#[derive(Default)]
struct PlusBounds {
    menu: Option<Bounds<Pixels>>,
    sub: Option<Bounds<Pixels>>,
    rows: HashMap<model::PlusSub, Bounds<Pixels>>,
}

/// A key in the + menu.
#[derive(Clone, Copy, PartialEq, Eq)]
enum PlusKey {
    Up,
    Down,
    Right,
    Left,
    Take,
    Shut,
}

/// One row of the chat's list.
#[derive(Clone, PartialEq)]
enum Row {
    Message(Message),
    Approval(Approval),
}

